// WBS-ORK 출력 파싱 — Webhook / Execute Workflow 양쪽 대응
const input = $input.first().json;
const d = input.body || input;

// 진척률 등급 이모지
const gradeEmoji = (grade) => {
  if (grade === 'GREEN')  return '🟢';
  if (grade === 'YELLOW') return '🟡';
  return '🔴';
};

// 진척률 등급 텍스트
const gradeText = (grade) => {
  if (grade === 'GREEN')  return '정상';
  if (grade === 'YELLOW') return '주의';
  return '위험';
};

// 날짜 포맷 (YYYY-MM-DD → YYYY-MM-DD (요일))
const toKorDate = (dateStr, dayName) => {
  if (!dateStr || dateStr === 'N/A') return 'N/A';
  return `${dateStr} (${dayName})`;
};

// 미완료 티켓 정리 (최대 5건 + 초과 처리)
const rawIncomplete = d.incomplete_tickets || [];
const visibleTickets = rawIncomplete.slice(0, 5);
const hiddenCount = rawIncomplete.length - visibleTickets.length;

const ticketLines = visibleTickets.map(t => {
  const id       = t.key || t.id || '?';
  const summary  = (t.summary || t.title || '제목 없음').substring(0, 40);
  const status   = t.status || 'Unknown';
  const assignee = t.assignee || '미배정';
  return `  • [${id}] ${summary} - ${status} (담당: ${assignee})`;
}).join('\n');

const incompleteSection = visibleTickets.length > 0
  ? ticketLines + (hiddenCount > 0 ? `\n  • 외 ${hiddenCount}건` : '')
  : '  • 미완료 티켓 없음';

// Commit Repo별 상세
const commitStats = d.commit_stats || {};
const repoCommitLines = Object.entries(commitStats)
  .map(([repo, cnt]) => `${repo}: ${cnt}`)
  .join(', ');
const commitDetail = repoCommitLines ? ` (${repoCommitLines})` : '';

// Gap 섹션 구성
const highCount   = d.high_gap_count   || 0;
const mediumCount = d.medium_gap_count || 0;
const lowCount    = d.low_gap_count    || 0;

// High Gap 상세 (최대 3건)
const highGaps = (d.all_gaps || []).filter(g => g.severity === 'high').slice(0, 3);
const highGapLines = highGaps.map(g =>
  `    🔴 ${g.source_agent}: ${(g.item || '').substring(0, 50)}`
).join('\n');

// Confluence URL
const pageId = $vars.CONFLUENCE_PAGE_ID || '371098596';
const baseUrl = ($vars.JIRA_BASE_URL || 'https://lgucorp.atlassian.net').replace(/\/$/, '');
const confluenceUrl = `${baseUrl}/wiki/spaces/${$vars.CONFLUENCE_SPACE_KEY || 'WCA'}/pages/${pageId}`;

// Teams 메시지 본문 조립
const progressEmoji = gradeEmoji(d.progress_grade);
const designEmoji   = gradeEmoji(d.design_grade);

const message = [
  `📊 [WBS Agent] 주간 개발 진척률 리포트`,
  `📅 기간: ${toKorDate(d.week_start, '월')} ~ ${toKorDate(d.week_end, '금')}`,
  ``,
  `━━━━━━━━━━━━━━━━━━━━━`,
  `🎯 전체 진척률: ${d.total_progress || 0}% ${progressEmoji} ${gradeText(d.progress_grade)}`,
  `━━━━━━━━━━━━━━━━━━━━━`,
  ``,
  `📋 Jira 티켓 현황`,
  `  • 전체: ${d.total_tickets || 0}개 | ✅ 완료: ${d.done_tickets || 0}개 | 🔄 진행중: ${d.in_progress_tickets || 0}개 | ⏳ 미착수: ${d.todo_tickets || 0}개`,
  `  • Story Point: ${d.sp_burned || 0} / ${d.sp_total || 0} 소진 (${d.sp_burned_rate || 0}%)`,
  ``,
  `💻 GitHub 활동`,
  `  • Commit: ${d.total_commits || 0}회${commitDetail}`,
  `  • 활성 개발일: ${d.max_active_days || 0}/5일`,
  ``,
  `📌 미완료 티켓`,
  incompleteSection,
  ``,
  `🔍 설계 적합성: ${d.design_score || 0}% ${designEmoji} (불일치 ${d.gap_count || 0}건)`,
  highCount   > 0 ? `  🔴 High: ${highCount}건` + (highGapLines ? `\n${highGapLines}` : '') : '',
  mediumCount > 0 ? `  🟡 Medium: ${mediumCount}건` : '',
  lowCount    > 0 ? `  🟢 Low: ${lowCount}건` : '',
  ``,
  `📎 상세 리포트: ${confluenceUrl}`
].filter(line => line !== null && line !== undefined).join('\n');

// 실패 Agent 경고
const failedWarning = (d.failed_agents || []).length > 0
  ? `\n\n⚠️ 일부 데이터 미수집: ${d.failed_agents.join(', ')} (Ollama 환경 이슈)`
  : '';

return [{ json: {
  ...d,
  teams_message:   message + failedWarning,
  confluence_url:  confluenceUrl,
  page_id:         pageId,
  base_url:        baseUrl,
  space_key:       $vars.CONFLUENCE_SPACE_KEY || 'WCA',
  report_timestamp: new Date().toISOString()
} }];

// Teams Adaptive Card — TextBlock + FactSet 만 사용 (최대 호환)
const d = $input.first().json;

const gradeEmoji = (g) => g === 'GREEN' ? '🟢' : g === 'YELLOW' ? '🟡' : '🔴';
const gradeText  = (g) => g === 'GREEN' ? '정상' : g === 'YELLOW' ? '주의' : '위험';

// 미완료 티켓 최대 5건
const rawTickets  = d.incomplete_tickets || [];
const tickets     = rawTickets.slice(0, 5);
const hiddenCount = rawTickets.length - tickets.length;
const ticketLines = tickets.map(t =>
  `• [${t.key || '?'}] ${(t.summary || '').substring(0, 30)} (${t.status || '?'}, ${t.assignee || '미배정'})`
).join('\n') + (hiddenCount > 0 ? `\n• 외 ${hiddenCount}건` : '');

// High Gap (최대 3건)
const highGaps = (d.all_gaps || []).filter(g => g.severity === 'high').slice(0, 3);
const gapLines = highGaps.map(g => `• ${g.source_agent}: ${(g.item || '').substring(0, 45)}`).join('\n');

const pe = gradeEmoji(d.progress_grade);
const de = gradeEmoji(d.design_grade);

const bodyItems = [
  { type: 'TextBlock', text: '📊 WBS Agent 주간 개발 진척률 리포트', weight: 'Bolder', size: 'Large', wrap: true },
  { type: 'TextBlock', text: `📅 ${d.week_start || 'N/A'} (월) ~ ${d.week_end || 'N/A'} (금)`, isSubtle: true, wrap: true },
  { type: 'TextBlock', text: `🎯 전체 진척률: ${d.total_progress || 0}% ${pe} ${gradeText(d.progress_grade)}  |  🔍 설계 적합성: ${d.design_score || 0}% ${de} ${gradeText(d.design_grade)}`, weight: 'Bolder', wrap: true },
  { type: 'TextBlock', text: '📋 Jira 티켓 현황', weight: 'Bolder' },
  {
    type: 'FactSet',
    facts: [
      { title: '전체', value: `${d.total_tickets || 0}개` },
      { title: '✅ 완료', value: `${d.done_tickets || 0}개` },
      { title: '🔄 진행중', value: `${d.in_progress_tickets || 0}개` },
      { title: '⏳ 미착수', value: `${d.todo_tickets || 0}개` },
      { title: 'Story Point', value: `${d.sp_burned || 0} / ${d.sp_total || 0} (${d.sp_burned_rate || 0}%)` }
    ]
  },
  { type: 'TextBlock', text: '💻 GitHub 활동', weight: 'Bolder' },
  {
    type: 'FactSet',
    facts: [
      { title: 'Commit', value: `${d.total_commits || 0}회` },
      { title: '활성 개발일', value: `${d.max_active_days || 0} / 5일` }
    ]
  }
];

if (tickets.length > 0) {
  bodyItems.push({ type: 'TextBlock', text: '📌 미완료 티켓', weight: 'Bolder' });
  bodyItems.push({ type: 'TextBlock', text: ticketLines, wrap: true, size: 'Small' });
}

if (d.gap_count > 0) {
  bodyItems.push({ type: 'TextBlock', text: `🔍 설계 Gap: 총 ${d.gap_count}건 (🔴 ${d.high_gap_count || 0} 🟡 ${d.medium_gap_count || 0} 🟢 ${d.low_gap_count || 0})`, weight: 'Bolder', wrap: true });
  if (gapLines) bodyItems.push({ type: 'TextBlock', text: gapLines, wrap: true, size: 'Small' });
}

if ((d.failed_agents || []).length > 0) {
  bodyItems.push({ type: 'TextBlock', text: `⚠️ 데이터 미수집: ${d.failed_agents.join(', ')}`, wrap: true, size: 'Small' });
}

const card = { type: 'AdaptiveCard', version: '1.0', body: bodyItems };

const teamsUrl = 'https://defaultdbebe70a4a5048ccb5a1e047510c68.a9.environment.api.powerplatform.com:443/powerautomate/automations/direct/workflows/a714a17a81c548a3a685a05298324a84/triggers/manual/paths/invoke?api-version=1&sp=%2Ftriggers%2Fmanual%2Frun&sv=1.0&sig=TlEvOZXV-83eDsfyHzr4NRnqceyDI1qHxuRXOL8gi4s';
return [{ json: { ...d, teams_payload: { attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', content: card }] }, teams_url: teamsUrl } }];

const teamsResult = $input.first().json;
const reportData  = $('Build Report Data').first().json;

const teamsUrl = $('Build Teams Card').first().json.teams_url || '';
const skipped  = !teamsUrl;
const success  = skipped ? false : (!teamsResult.error && ((teamsResult.statusCode || 200) < 400));

return [{ json: {
  teams_sent:   success,
  teams_skipped: skipped,
  teams_status: skipped ? null : (teamsResult.statusCode || 200),
  teams_error:  skipped ? 'TEAMS_WEBHOOK_URL 미설정' : (teamsResult.error || null),
  ...reportData
} }];
